const { execFileSync } = require('child_process');

const requestScript = `
fetch('http://host.docker.internal:8787/run', { method: 'POST' })
  .then(async (response) => {
    const text = await response.text();
    if (!response.ok) {
      console.error(text);
      process.exit(1);
    }
    console.log(text);
  })
  .catch((error) => {
    console.error(error.stack || error.message || String(error));
    process.exit(1);
  });
`;

const output = execFileSync('node', ['-e', requestScript], {
  cwd: '/workspace',
  encoding: 'utf8',
  timeout: 10 * 60 * 1000,
});

const result = JSON.parse(output);
let parsed = result;
if (result.stdout) {
  try {
    parsed = JSON.parse(result.stdout);
  } catch (error) {
    parsed = result;
  }
}

return [{ json: parsed }];
